class PublisherTest implements Consumer<String> {   // the test is the collaborator
    private final List<String> seen = new ArrayList<>();
    @Override public void accept(String e) { seen.add(e); }

    @Test void publishesOnce() {
        Publisher p = new Publisher(this);          // install the test object itself
        p.change("x");
        assertEquals(List.of("x"), seen);
    }
}
